que () # n_concentrations # Time array (n_concentrations, n_timepoints). The values are time in seconds. time_array = np . array ( list ( df [ df [ L [ "chamber_IDs" ]] == df [ L [ "chamber_IDs" ]][ 0 ]] # Get just the first chamber . groupby ( L [ 'concentration' ])[ L [ 'time' ]] # Group by the concentration column, and get just the time values. . apply ( list )) ) # And convert the times for each concentration to a list. # Then we convert to a list of lists, and then to a numpy array. # RFU array (n_concentrations, n_timepoints, n_chambers) RFU_list_by_conc = [] for conc_index , concentration in enumerate ( concentrations ): time_values = time_array [ conc_index ] #print(time_values) RFU_list_by_time = [] for time_index , time in enumerate ( time_values ): # Get the RFU values for this concentration and time rfu_values = df [( df [ L [ 'concentration' ]] == concentration ) & ( df [ L [ 'time' ]] == time )][ L [ 'luminance' ]] . to_list () RFU_list_by_time . append ( rfu_values ) # Append the RFU values for this concentration to the list RFU_list_by_conc . append ( RFU_list_by_time ) # Convert the list to a numpy array RFU_array = np . array ( RFU_list_by_conc ) # Expand by 1 axis so it's (n_concentrations, n_timepoints, n_chambers, 1) RFU_array = RFU_array [ ... , np . newaxis ] ### Adding units: concentrations = concentrations * conc_unit button_quant = button_quant * units . RFU time_array = time_array * time_unit ### Create the data object: from mercury.db_api.data import Data4D , IndepVars , Meta # Independent variables: indep_vars = IndepVars ( concentrations , chamber_ids , sample_ids , button_quant , time_array ) # Meta data: meta = Meta () # Currently empty, but can be extended in the future. # 3D Data object: data_4d = Data4D ( indep_vars = indep_vars , meta = meta , dep_var = RFU_array , dep_var_type = [ 'luminance' ], dep_var_units = [ units . RFU ]) return data_4d Input / Output Helpers mercury.db_api.io load_button_quant_from_csv ( csv_path ) Loads a